use vstd::prelude::*;

verus! {

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
    requires
        s1.len() == s2.len() && s2.len() == s3.len(),
        (3 * s1.len() as i64) <= i32::MAX as i64, // fit in i32 range (wider arithmetic for safety)
    ensures
        res.len() == 3 * s1.len(),
        forall(|i: int| 0 <= i && i < s1.len() as int ==> 
            res[(3 * i) as usize] == s1[i as usize] &&
            res[(3 * i + 1) as usize] == s2[i as usize] &&
            res[(3 * i + 2) as usize] == s3[i as usize]
        ),
{
    let n = s1.len();
    let mut res = Vec::<i32>::with_capacity(3 * n);
    let mut i: usize = 0;
    while i < n
        invariant i <= n,
        invariant res.len() == 3 * i,
        invariant forall(|j: int| 0 <= j && j < i as int ==>
            res[(3*j) as usize] == s1[j as usize] &&
            res[(3*j + 1) as usize] == s2[j as usize] &&
            res[(3*j + 2) as usize] == s3[j as usize]
        ),
        decreases n - i,
    {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
        i = i + 1;
    }
    res
}

}
